select * from yh_sport_recommend_record rd,yh_disease_category ry,yh_sport_setmeal yh

rd.diseaseid=ry.id
and yh.id=rd.setmealid
and
rd.user_code=#{userCode,jdbcType=VARCHAR}

order by rd.record_data desc LIMIT  #{page},#{limit}

select count(*) from yh_sport_recommend_record rd,yh_disease_category ry,yh_sport_setmeal yh
rd.diseaseid=ry.id and yh.id=rd.setmealid and rd.user_code=#{userCode,jdbcType=VARCHAR}
order by rd.record_data desc
